mapper.select:
SELECT device_token_id, member_id, token, platform, created_at, updated_at
FROM device_token
WHERE token = #{token}

mapper.update:
UPDATE device_token
SET member_id = #{memberId}
WHERE token = #{token}

mapper.select:
SELECT device_token_id, member_id, token, platform, created_at, updated_at
FROM device_token
WHERE member_id = #{memberId}
